package org.freecad.mobilelab;
import org.json.*;
public final class PartDesignAttachmentAdapterHostTest {
    static int checks;
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
    static JSONObject call(JSONObject q)throws Exception{JSONObject r=new JSONObject(CoreNative.request(q.toString()));check(r.getBoolean("ok"),r.optString("error"));return r.getJSONObject("state");}
    static JSONObject cmd(String s)throws Exception{return call(CoreCommandLine.parse(s));}
    static void bad(String s)throws Exception{JSONObject r=new JSONObject(CoreNative.request(CoreCommandLine.parse(s).toString()));check(!r.getBoolean("ok"),"Must reject "+s);}
    static void python(String code)throws Exception{JSONObject r=call(new JSONObject().put("op","python").put("code",code)).getJSONObject("python").getJSONObject("console");check(r.getString("error").isEmpty(),r.getString("error"));}
    static void volume(String n,double expected)throws Exception{JSONObject r=cmd("ShapeInfo "+n).getJSONObject("shape_inspection");check(r.getBoolean("valid")&&r.getInt("solids")==1,"Closed native single solid");check(Math.abs(r.getDouble("volume")-expected)<1e-5,"Analytic volume "+n+": "+r);}
    public static void main(String[] a)throws Exception{
        System.load(a[3]);SignalProbe.capture();System.load(a[0]);CoreNative.initialize(a[1],a[2],a[1]);check(SignalProbe.preserved(),"JVM signals retained");
        cmd("NewDoc Attachments");cmd("Body Body");cmd("BodySketch Body StockProfile");
        for(String line:new String[]{"0 0 10 0","10 0 10 10","10 10 0 10","0 10 0 0"})cmd("SketchLine StockProfile "+line);
        for(int i=0;i<4;i++)cmd("Constraint StockProfile Block "+i);
        cmd("Pad Body StockProfile Stock 10");volume("Body",1000);
        cmd("BodyPlane Body Plane 20 20");cmd("BodyAxis Body Axis 20");cmd("BodyPoint Body Point");cmd("BodyFrame Body Frame");
        cmd("DatumAttach Body Plane Stock Face6");cmd("DatumAttach Body Axis Stock Edge1");cmd("DatumAttach Body Point Stock Vertex1");
        python("d=App.ActiveDocument\nassert d.Plane.MapMode=='FlatFace' and d.Axis.MapMode=='Tangent' and d.Point.MapMode=='Vertex'\nassert d.Plane.AttachmentSupport[0][0]==d.Stock and d.Axis.AttachmentSupport[0][0]==d.Stock and d.Point.AttachmentSupport[0][0]==d.Stock\nassert (d.Point.Shape.Vertexes[0].Point-d.Stock.Shape.Vertexes[0].Point).Length<1e-8\nedge=d.Stock.Shape.Edges[0]\nassert abs(d.Axis.Placement.Rotation.multVec(App.Vector(0,0,1)).dot(edge.tangentAt(edge.FirstParameter)))>1-1e-8\nassert abs(d.Plane.Placement.Base.z-10)<1e-8\nassert d.Body.Tip==d.Stock");
        for(String n:new String[]{"Plane","Axis","Point"}){JSONObject info=cmd("DatumInfo "+n).getJSONObject("datum_inspection");check(info.getJSONArray("support").getJSONObject(0).getString("object").equals("Stock"),"Native support inspection");WireFrame w=new WireFrame(cmd("DatumPreview "+n).getJSONObject("wire_preview"));check(w.pointCount<32,"Finite construction guide");bad("Preview "+n);bad("ShapeInfo "+n);}
        for(String s:new String[]{"DatumAttach Body Frame Stock Face6","DatumAttach Body Plane Stock Edge1","DatumAttach Body Axis Stock Face1","DatumAttach Body Point Stock Edge1","DatumAttach Body Plane Stock Face65","DatumAttach Body Axis Stock Edge257","DatumAttach Body Point Stock Vertex513","DatumAttach Body Point Stock Vertex99","DatumAttach Body Plane Frame Face1","DatumAttach Body Plane Plane Face1","DatumPose Body Plane 0 0 0 0 0 0","Set Plane.AttachmentSupport 0","Set Plane.MapMode 0","DatumDetach Body Frame"})bad(s);
        cmd("Set Stock.Length 12 mm");volume("Body",1200);check(Math.abs(cmd("DatumInfo Plane").getJSONObject("datum_inspection").getJSONArray("origin_mm").getDouble(2)-12)<1e-8,"Source dimensional dependency");
        cmd("DatumDetach Body Point");python("d=App.ActiveDocument\nassert d.Point.MapMode=='Deactivated' and not d.Point.AttachmentSupport");cmd("Undo");python("assert App.ActiveDocument.Point.MapMode=='Vertex'");cmd("Redo");cmd("Undo");
        cmd("DatumDetach Body Plane");cmd("Set Stock.Length 11 mm");python("assert abs(App.ActiveDocument.Plane.Placement.Base.z-12)<1e-8");cmd("DatumAttach Body Plane Stock Face6");python("assert abs(App.ActiveDocument.Plane.Placement.Base.z-11)<1e-8");cmd("Set Stock.Length 10 mm");
        cmd("BodySketchDatum Body Plane Profile");cmd("SketchCircle Profile 0 0 1");cmd("Constraint Profile Block 0");cmd("SketchOffset Profile 2 3 0 20 0 0");cmd("Pad Body Profile Boss 4");volume("Body",1000+4*Math.PI);
        python("d=App.ActiveDocument\nexpected=d.Plane.Placement.multiply(d.Profile.AttachmentOffset)\nassert (d.Profile.Placement.Base-expected.Base).Length<1e-8 and d.Profile.Placement.Rotation.isSame(expected.Rotation,1e-8)\nassert abs(d.Profile.Placement.Base.x-2)<1e-8 and abs(d.Profile.Placement.Base.y-3)<1e-8\nassert d.Boss.Profile[0]==d.Profile and d.Body.Tip==d.Boss");
        bad("DatumAttach Body Plane Boss Face6");bad("DatumAttach Body Axis Profile Edge1");bad("RemoveDatum Body Plane");bad("RemoveBodyFeature Body Stock");
        bad("SketchOffset Profile 1000001 0 0 0 0 0");bad("SketchOffset Profile 999999 0 0 0 0 0");bad("SketchOffset Profile 2 3 1 0 0 0");volume("Body",1000+4*Math.PI);
        cmd("Set Stock.Length 12 mm");volume("Body",1200+4*Math.PI);python("assert abs(App.ActiveDocument.Profile.Placement.Base.z-12)<1e-8");
        cmd("SketchOffset Profile 3 4 0 30 0 0");volume("Body",1200+4*Math.PI);cmd("Undo");cmd("Redo");cmd("Undo");
        cmd("Begin AtomicAttachment");cmd("SketchOffset Profile 4 4 0 0 0 0");bad("DatumAttach Body Plane Boss Face6");python("assert abs(App.ActiveDocument.Profile.AttachmentOffset.Base.x-2)<1e-8");volume("Body",1200+4*Math.PI);
        cmd("PartPlacement Body 5 6 7 30 20 10");volume("Body",1200+4*Math.PI);python("d=App.ActiveDocument\nfor o in (d.Plane,d.Axis,d.Point):assert (o.getGlobalPlacement().Base-d.Body.Placement.multVec(o.Placement.Base)).Length<1e-8");cmd("Undo");
        cmd("Body RoundBody");cmd("BodySketch RoundBody RoundProfile");cmd("SketchCircle RoundProfile 0 0 5");cmd("Constraint RoundProfile Block 0");cmd("Pad RoundBody RoundProfile RoundPad 10");cmd("BodyPlane RoundBody RoundPlane 20 20");cmd("BodyAxis RoundBody RoundAxis 20");cmd("BodyPoint RoundBody RoundPoint");
        bad("DatumAttach RoundBody RoundPlane RoundPad Face1");bad("DatumAttach RoundBody RoundAxis RoundPad Edge2");bad("DatumAttach RoundBody RoundPoint Stock Vertex1");bad("DatumAttach Body Point RoundPad Vertex1");
        cmd("DatumAttach RoundBody RoundPoint RoundPad Vertex1");bad("RemoveBodyFeature RoundBody RoundPad");
        cmd("BodySketchDatum RoundBody RoundPlane BudgetProfile");bad("SketchOffset BudgetProfile 1000001 0 0 0 0 0");
        cmd("Body HoleBody");cmd("BodySketch HoleBody HoleBase");cmd("SketchCircle HoleBase 0 0 6");cmd("Constraint HoleBase Block 0");cmd("Pad HoleBody HoleBase HoleStock 10");cmd("BodyPlane HoleBody HolePlane 20 20");cmd("DatumAttach HoleBody HolePlane HoleStock Face3");cmd("BodySketchDatum HoleBody HolePlane HoleProfile");cmd("SketchCircle HoleProfile 0 0 1");cmd("Constraint HoleProfile Block 0");cmd("SketchOffset HoleProfile 2 1 0 30 0 0");cmd("BodyHole HoleBody HoleProfile Hole 2 4");volume("HoleBody",356*Math.PI);bad("SketchOffset HoleProfile 2 1 -1 0 0 0");bad("SketchOffset HoleProfile 2 1 0 0 30 0");volume("HoleBody",356*Math.PI);
        cmd("Body PipeBody");cmd("BodyPlane PipeBody SectionPlane 20 20");cmd("BodySketchDatum PipeBody SectionPlane PipeProfile");cmd("SketchCircle PipeProfile 0 0 1");cmd("Constraint PipeProfile Block 0");cmd("BodySketch PipeBody PipePath");cmd("SketchLine PipePath 0 0 0 6");cmd("Constraint PipePath Block 0");cmd("SketchPlane PipePath XZ 0 0 0");cmd("BodyAddPipe PipeBody PipeProfile PipePath Edge1 Pipe");volume("PipeBody",6*Math.PI);bad("SketchOffset PipeProfile 1 0 0 0 0 0");bad("SketchOffset PipeProfile 0 0 1 0 0 0");volume("PipeBody",6*Math.PI);
        cmd("Body HelixBody");cmd("BodyPlane HelixBody Meridian 20 20");cmd("DatumPose HelixBody Meridian 0 0 0 0 0 90");cmd("BodySketchDatum HelixBody Meridian Radial");cmd("SketchCircle Radial 5 0 0.5");cmd("Constraint Radial Block 0");cmd("BodyAddHelix HelixBody Radial Helix 3 6");cmd("SketchOffset Radial 1 0 0 0 0 0");check(Math.abs(cmd("ShapeInfo HelixBody").getJSONObject("shape_inspection").getDouble("volume")-6*Math.PI*Math.PI)<0.001,"Native helix radius follows composed sketch offset");bad("SketchOffset Radial 0 0 0 0 0 90");
        cmd("Save Attachments.FCStd");
        Process cold=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-cp",System.getProperty("java.class.path"),"org.freecad.mobilelab.PartDesignAttachmentColdRestoreHostTest",a[0],a[1],a[2]).inheritIO().start();check(cold.waitFor()==0,"Native support restoration in a fresh JVM/interpreter");
        python("import zipfile,xml.etree.ElementTree as ET,mobile_core\nroot=mobile_core._root\nwith zipfile.ZipFile(root/'Attachments.FCStd') as z:saved={n:z.read(n) for n in z.namelist()}\ndef attachment_fixture(filename,obj,prop,tag,key,value):\n    tree=ET.fromstring(saved['Document.xml'])\n    node=tree.find(\"./ObjectData/Object[@name='\"+obj+\"']/Properties/Property[@name='\"+prop+\"']/\"+tag)\n    assert node is not None\n    node.set(key,value)\n    xml=ET.tostring(tree)\n    with zipfile.ZipFile(root/('BadAttachment'+filename+'.FCStd'),'w') as z:\n        for n,b in saved.items():z.writestr(n,xml if n=='Document.xml' else b)");
        String[] changes={"'PlaneMode','Plane','MapMode','Integer','value','2'","'AxisMode','Axis','MapMode','Integer','value','5'","'PointMode','Point','MapMode','Integer','value','24'","'PlaneKind','Plane','AttachmentSupport','LinkSubList/Link','sub','Edge1'","'AxisKind','Axis','AttachmentSupport','LinkSubList/Link','sub','Face1'","'PointKind','Point','AttachmentSupport','LinkSubList/Link','sub','Face1'","'FaceBudget','Plane','AttachmentSupport','LinkSubList/Link','sub','Face65'","'EdgeBudget','Axis','AttachmentSupport','LinkSubList/Link','sub','Edge257'","'VertexBudget','Point','AttachmentSupport','LinkSubList/Link','sub','Vertex513'","'Count','Plane','AttachmentSupport','LinkSubList','count','0'","'Foreign','Plane','AttachmentSupport','LinkSubList/Link','obj','RoundPad'","'Cycle','Plane','AttachmentSupport','LinkSubList/Link','obj','Boss'","'SketchSource','Axis','AttachmentSupport','LinkSubList/Link','obj','Profile'","'RootOffset','Plane','AttachmentOffset','PropertyPlacement','Px','1'","'OffsetRange','Profile','AttachmentOffset','PropertyPlacement','Px','1000001'","'OffsetNan','Profile','AttachmentOffset','PropertyPlacement','Q0','nan'","'OffsetQuaternion','Profile','AttachmentOffset','PropertyPlacement','Q3','0'","'Reverse','Plane','MapReversed','Bool','value','true'","'PathParameter','Axis','MapPathParameter','Float','value','0.5'"};
        for(String mutation:changes)python("attachment_fixture("+mutation+")");
        for(String n:new String[]{"PlaneMode","AxisMode","PointMode","PlaneKind","AxisKind","PointKind","FaceBudget","EdgeBudget","VertexBudget","Count","Foreign","Cycle","SketchSource","RootOffset","OffsetRange","OffsetNan","OffsetQuaternion","Reverse","PathParameter"})bad("Open BadAttachment"+n+".FCStd");
        volume("Body",1200+4*Math.PI);cmd("ExportStep Body AttachmentDriven.step");cmd("ImportStep Copy AttachmentDriven.step");volume("Copy",1200+4*Math.PI);
        cmd("Close");cmd("Open Attachments.FCStd");volume("Body",1200+4*Math.PI);python("d=App.ActiveDocument\nassert d.Plane.AttachmentSupport[0][0]==d.Stock and d.Axis.AttachmentSupport[0][0]==d.Stock and d.Point.AttachmentSupport[0][0]==d.Stock\nassert abs(d.Profile.AttachmentOffset.Base.x-2)<1e-8 and d.Body.Tip==d.Boss");
        System.out.println("PASS original attachment JNI checks: "+checks);
    }
}
